/**
 * M7 static foods: the Thai dish estimates (generated by scripts/build-foods.mjs from
 * thaiDishes.src.json, values per typical plate with Small / Regular / Large portions) and the
 * seed foods (the "Protein shake" placeholder). Both are small, so they're bundled; the big USDA
 * subset is lazy-loaded by foodDb.ts instead.
 */
import type { Food } from '../../core/types';
import thaiDishes from './thaiDishes.json';
import seedFoods from './seedFoods.json';

export const THAI_DISHES: readonly Food[] = thaiDishes.foods as Food[];

export const SEED_FOODS: readonly Food[] = seedFoods.foods as Food[];

/** The seed "Protein shake" (placeholder values; edit from the product label). */
export const PROTEIN_SHAKE_ID = 'seed:protein-shake';

/** Seed foods whose placeholder values the app asks to replace from the label on first log. */
export const EDIT_FROM_LABEL: ReadonlySet<string> = new Set(seedFoods.editFromLabel);

const BY_ID = new Map<string, Food>([...SEED_FOODS, ...THAI_DISHES].map((f) => [f.id, f]));

/** A Thai dish or seed food by id. */
export function findStaticFood(id: string): Food | undefined {
  return BY_ID.get(id);
}
